quests[32501] = { id = 32501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer in der Tonlongsteppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[32502] = { id = 32502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer im Tal der Vier Winde.", sourceObjectiveStatus = "unverified-source-field" }
quests[32503] = { id = 32503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!" }
quests[32504] = { id = 32504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Die Geheimnisse von Sturmwind", description = "Schickt Truppen in verdeckter Mission in das Herz des feindlichen Gebietes, um ihre Pläne zu erfahren." }
quests[32509] = { id = 32509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme" }
quests[32510] = { id = 32510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme" }
quests[32603] = { id = 32603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fabelhafte Wesen", description = "Habt Ihr je das große Buch der pandarischen Fabeln gelesen? Die Pandaren reichen diese Geschichten an ihre Kinder weiter – die Geschichte von der Grille und dem Falken, oder der langsamen Schildkröte – um sie Lektionen zu lehren, die ihnen in ihrem späteren Leben von Nutzen sein werden. Was nur wenige Kinder wissen ist, dass es diese Kreaturen wirklich gibt, hier in Pandaria! Obwohl die Geschichten ihrer Reisen erfunden sind, sind sie doch mächtige Bewohner dieser Welt. Solltet Ihr ihnen auf Euren Reisen begegnen, könnt Ihr die Macht Eurer Haustiere gegen diese sagenumwobenen Gestalten auf die Probe stellen.", sourceObjective = "Besiegt die Elite-Kampfhaustiere der pandarischen Fabelwelt.", completion = "Ihr habt sie alle gefunden? Unglaublich! Die Geschichten sind also doch wahr! Vielleicht werdet Ihr ja die nächste große pandarische Fabel schreiben, über Eure eigene unglaubliche Reise!", sourceObjectiveStatus = "unverified-source-field" }
quests[32604] = { id = 32604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fabelhafte Wesen, Buch I", description = "Die Geschichten von Ka'wi dem Schlinger, Nitun, Kafi und Dos-Ryga werden in diesem Land immer präsent bleiben. Möchtet Ihr ihnen noch einmal im Kampf begegnen?", sourceObjective = "Besiegt Ka'wi den Schlinger, Nitun, Kafi und Dos-Ryga.", completion = "Ich verneige mich vor Euch, die weiterhin auf den Spuren der großen pandarischen Fabeln wandelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32618] = { id = 32618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Randal Weidmann im Holzfällerlager des Osttals im Wald von Elwynn. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Randal Weidmann.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt Katie Weidmann hier im Lager finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32661] = { id = 32661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Aalun am Eingang zur Exodar auf der Azurmythosinsel. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Aalun.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Torallius ist gleich dort drüben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32662] = { id = 32662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Ultham am Gehöft Bernruh in Dun Morogh, an der östlichen Straße aus Eisenschmiede heraus. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Ultham Eisenhorn.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Veron Bernruh steht direkt vorm Tor des Gehöfts.", sourceObjectiveStatus = "unverified-source-field" }
quests[32663] = { id = 32663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Binjy Federpfiff bei Stahlrosts Depot in Dun Morogh. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Binjy Federpfiff.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Milli befindet sich gleich dort drüben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32664] = { id = 32664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Jartsam in der Enklave des Cenarius in Darnassus. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Jartsam.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt hier bei Lelanai erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32665] = { id = 32665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Mei Lin nördlich des Zwergenviertels in Sturmwind. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Mei Lin.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt hier beim alten Weißnase erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32667] = { id = 32667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Sanftpfote im Tal der Ehre in Orgrimmar. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Sanftpfote.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt hier bei Schildkrötenmeisterin Odai erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32668] = { id = 32668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Perascamin bei Thurons Aufzucht, südöstlich vom Hirtentor von Silbermond aus. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Perascamin.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt draußen bei Winaestra erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32669] = { id = 32669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Kildar im Tal der Ehre in Orgrimmar. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Kildar.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es drüben bei Ogunaro erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32670] = { id = 32670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Kar Sturmsang im Dorf der Bluthufe in Mulgore. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Kar Sturmsang.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es drüben bei Harb Klauenhuf erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32671] = { id = 32671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Xar'Ti in Sen'jin im südlichen Durotar. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Xar'Ti.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es drüben bei Zjolnir erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32672] = { id = 32672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Velma Warnam in Brill in Tirisfal. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Velma Warnam.", completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt hier bei Zachariah Post erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32673] = { id = 32673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt Reiten", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Levi Ladestock im Tal der Geister in Orgrimmar. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", sourceObjective = "Findet Levi Ladestock.", sourceObjectiveStatus = "unverified-source-field" }
quests[32674] = { id = 32674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Fliegen ist leichter", description = "Der Himmel ruft Euch! Es ist Zeit, Fliegen zu lernen!\n\nBesucht Maztha die Fluglehrerin am Himmelspfad in Orgrimmar.\n\nUnd vergesst nicht, ein Flugreittier zu erwerben!", sourceObjective = "Findet Maztha.", completion = "Ah, gut Euch zu sehen. Ihr seht aus, als wärt Ihr bereit, Euch in die Lüfte zu schwingen!\n\nDenkt daran, Ihr könnt ein Flugreittier von Drakma hinter mir kaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32675] = { id = 32675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Fliegen ist leichter", description = "Der Himmel ruft Euch! Es ist Zeit, Fliegen zu lernen!\n\nBesucht die Fluglehrerin Bralla Wolkenflug am Greifenhorst in Sturmwind.\n\nUnd vergesst nicht, ein Flugreittier zu erwerben!", sourceObjective = "Findet Bralla Wolkenflug.", completion = "Ah, gut Euch zu sehen. Ihr seht aus, als wärt Ihr bereit, Euch in die Lüfte zu schwingen!\n\nDenkt daran, Ihr könnt ein Flugreittier von Tannec Steinschnabel da drüben kaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32682] = { id = 32682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gute Erde", description = "Wie Ihr wisst, {name}, werde ich nicht jünger. Man kann nicht für immer ein drahtiger junger Pandaren bleiben, wisst Ihr.\n\nIch suche jemanden, der meine Pflichten hier im Bund der Ackerbauern übernimmt, und niemand wäre geeigneter als Bauer Yoon.\n\nEr hat noch viel zu lernen, aber er hat einen brauchbaren Kopf auf den Schultern und, was wichtiger ist, ein großzügiges Herz.\n\nGlaubt Ihr, er könnte Interesse haben?", sourceObjective = "Sprecht mit Bauer Yoon.", completion = "Ich wusste doch, dass Ihr ihn überzeugen würdet, {name}. Ihr habt mein Herz beruhigt, nun da ich weiß, dass die Ackerbauern in guten Händen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[32686] = { id = 32686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloses Banner des Mantisreiches", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", sourceObjective = "Stellt das Artefakt zur Schau.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32687] = { id = 32687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloser uralter Harzspender", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", sourceObjective = "Stellt das Artefakt zur Schau.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32688] = { id = 32688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makellose alte Gottesanbeterin", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", sourceObjective = "Stellt das Artefakt zur Schau.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32689] = { id = 32689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloser Schallsignalgeber", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", sourceObjective = "Stellt das Artefakt zur Schau.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
