quests[32691] = { id = 32691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makellose Mantislampe", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", sourceObjective = "Stellt das Artefakt zur Schau.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32692] = { id = 32692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloser Pollensammler", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", sourceObjective = "Stellt das Artefakt zur Schau.", sourceObjectiveStatus = "unverified-source-field" }
quests[32693] = { id = 32693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloser Kypariharzbehälter", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", sourceObjective = "Stellt das Artefakt zur Schau.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32723] = { id = 32723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "recycelt mich", description = "Ihr habt noch mehr zu tun. \n\nTötet Itoka, den Meister der Schmiede, und findet ein Kodexfragment bei Fleischschmied Hoku, dem Torhüter des Donnerkönigs.", sourceObjective = "Tötet den Meister der Schmiede und sammelt ein Kodexfragment vom Mogutorhüter auf der Insel des Donners ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[32836] = { id = 32836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine billige Brummelflüte", description = "Die \"Brummelflüte\" wurde unsorgfältig aus einer Baumwurzel geschnitzt und die Abstände zwischen den Löchern sind unregelmäßig.\n\nBei genauerem Hinschauen entdeckt Ihr auf der Unterseite eingeritzte Wörter:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt die billige Brummelflüte zu einem Mitglied der Kampfgilde Eurer Fraktion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32838] = { id = 32838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Fabel von Liebe und Edelmut", description = "Ein kleines Kinderbuch. Es ist gebunden und in ziemlich gutem Zustand.\n\nAuf dem hinteren Buchdeckel entdeckt Ihr neben dem Buchrücken in kursiver Handschrift folgende Aufschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt \"Der Bär und die Jungfrau hehr\" zu einem Mitglied der Kampfgilde Eurer Fraktion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32840] = { id = 32840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don-Dons Lunte", description = "Inmitten der Fleisch- und Fellstückchen von Ho-zen, die wild um Kota Kons zerstörerische Sphäre wirbeln, scheint Ihr eine kurze Lunte erwischt zu haben.\n\nSie besteht ausschließlich aus verwobenen und verfilzten Ho-zen-Haaren und riecht stark.\n\nAm einen Ende der Zündschnur entdeckt Ihr ein kleines Papieretikett mit folgender Aufschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt Don-Dons Lunte zu einem Mitglied der Kampfgilde Eurer Fraktion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32842] = { id = 32842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zähne wie Messer", description = "Der Zahn spitzt sich zu einer scharfen Kante zu, fast wie wenn er geschärft worden wäre. Er gehörte offensichtlich einer wilden Bestie.\n\nWährend Ihr ihn behutsam in der Hand haltet, fällt Euch eine gekonnt eingravierte Inschrift auf:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt den ausgesprochen scharfen Zahn zu einem Mitglied der Kampfgilde Eurer Fraktion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32844] = { id = 32844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnis des Schleims", description = "Der Inhalt der Phiole wirbelt und schäumt wild, was sie in Eurer Hand zittern lässt. Als Ihr hineinschaut, glaubt Ihr, kurz einen Blick auf ein wütendes lebendes Gesicht zu erhaschen.\n\nDer Pfropfen der Flasche passt genau. An seinem Rand entdeckt Ihr eine geschickt eingeschnitzte Inschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt die Phiole mit rötlichem Schleim zu einem Mitglied der Kampfgilde Eurer Fraktion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32846] = { id = 32846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modifizierter Mampfapparat", description = "Ihr hättet diesen modifizierten Mampfapparat vielleicht gar nicht als solchen erkannt, wenn jemand nicht groß \"MODIFIZIERTER MAMPFAPPARAT\" darauf gekritzelt hätte.\n\nGleich unter der schludrig gemalten Aufschrift seht Ihr eine kleinere, in leuchtend roter Tinte und viel schöner geschrieben:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt den modifizierten Mampfapparat zu einem Mitglied der Kampfgilde Eurer Fraktion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32848] = { id = 32848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostige Eierschale", description = "Ein Stück einer Eierschale, wahrscheinlich von einem Pinguin. Die Ränder sind mit Raureif bedeckt und die Krümmung zeigt, dass das intakte Ei ziemlich groß gewesen sein muss.\n\nKomischerweise steht im Inneren der Eierschale mit jadegrüner Tinte eine Nachricht geschrieben:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt die frostige Eierschale zu einem Mitglied der Kampfgilde Eurer Fraktion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32850] = { id = 32850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modell vom letzten Jahr", description = "Dieser Roboter ist in einem schlechten Zustand. Er hat mehrere eingebaute Sockel, die wahrscheinlich wie beim Blingtron 4000 einst Edelsteine enthielten, jetzt aber leer sind.\n\nAuf der sonst staubbedeckten Hinterseite des Roboters seht Ihr ein glänzendes kleines Metallschild mit folgender geprägter Inschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt den staubigen alten Roboter zu einem Mitglied der Kampfgilde Eurer Fraktion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32852] = { id = 32852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Erdschneider des Grabungsmeisters", description = "Dem Aussehen nach ein ganz gewöhnlicher Spaten. Am Griff ist in Kursivschrift \"Der Erdschneider des Grabungsmeisters\" eingeschnitzt.\n\nAuf der anderen Seite des Griffs entdeckt Ihr jedoch ein kleineres Etikett in einfacher Schrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt den Erdschneider des Grabungsmeisters zu einem Mitglied der Kampfgilde Eurer Fraktion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32854] = { id = 32854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgetragene Augenbinde", description = "Ein Stück Stoff, das um einen menschlichen Kopf passen würde. Der Stoff ist schlicht und schmucklos, abgesehen von einem kleinen Etikett am einen Ende mit folgender Aufschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt die abgetragene Augenbinde zu einem Mitglied der Kampfgilde Eurer Fraktion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32856] = { id = 32856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Papier umwickelter Stein", description = "Eine seltsame Kombination. Das Papier umschließt den Stein vollständig, der im Vergleich dazu kaum größer als ein Kiesel ist.\n\nWenn Ihr das Papier gegen das Licht haltet, seht Ihr ein deutliches Wasserzeichen mit folgendem Text:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt den mit Papier umwickelten Stein zu einem Mitglied der Kampfgilde Eurer Fraktion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32857] = { id = 32857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ro-Shambo", description = "Mit der Herausforderungskarte, die Ihr freigeschaltet habt, dürft Ihr Ro-Shambo herausfordern, eine esoterische Kreatur aus unbekannten Gefilden.\n\nPasst auf. Wie ich höre, hat er einige Tricks auf Lager.", sourceObjective = "Besiegt Ro-Shambo, indem Ihr seine Herausforderungskarte erwerbt und ihn in der Kampfgilde herausfordert.", sourceObjectiveStatus = "unverified-source-field" }
quests[32858] = { id = 32858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptorbalgboxhandschuhe", description = "Die Handschuhe sind mit groben Stichen genäht und wurden nach dem Geruch zu urteilen mit Kriechersekret behandelt. Sie erscheinen dennoch strapazierfähig und funktionstüchtig.\n\nIhr seid nicht sehr erstaunt, als Ihr im Innensaum folgende Aufschrift entdeckt:\n\nZUR KAMPFGILDE ZURÜCKBRINGEN", sourceObjective = "Bringt die Raptorbalgboxhandschuhe zu einem Mitglied der Kampfgilde Eurer Fraktion.", sourceObjectiveStatus = "unverified-source-field" }
quests[32863] = { id = 32863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wofür wir trainiert haben", description = "Seid Ihr bereit, Eure Haustiere einer Prüfung zu unterziehen? Die Kampfhaustierarena ist kein Platz für niedrigstufige Angsthasen. Besser, Ihr habt einen Raketenbot dabei und seid auf alles gefasst. Wenn Ihr über drei vollständig ausgebildete Haustiere verfügt, dann sucht Kämpfe gegen Trainer mit ähnlichen Fähigkeiten und zeigt der Welt, was Ihr drauf habt. Die Anweisungen dazu findet Ihr in Eurem Wildtierführer.", sourceObjective = "Besiegt 10 Spieler über 'Kampf finden' mit einer Gruppe aus Haustieren auf Stufe 25.", completion = "Ich hörte Geschichten über einige Eurer Kämpfe. Offensichtlich waren sie vielen ein unvergessliches Erlebnis! Ich glaube, dass Ihr Euch diese Belohnung verdient habt. Glückwunsch, Trainer, und leistet weiterhin so gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32868] = { id = 32868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fabelhafte Wesen, Buch II", description = "Die Geschichten von Glückspilz Yi, Grauhuf und Huscher Xi'a werden in diesem Land immer präsent bleiben. Möchtet Ihr ihnen noch einmal im Kampf begegnen?", sourceObjective = "Besiegt Glückspilz Yi, Grauhuf und Huscher Xi'a.", completion = "Ich verneige mich vor Euch, die weiterhin auf den Spuren der großen pandarischen Fabeln wandelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32869] = { id = 32869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fabelhafte Wesen, Buch III", description = "Die Geschichten von No-No, Ti'un dem Wanderer und Blutstachel werden in diesem Land immer präsent bleiben. Möchtet Ihr ihnen noch einmal im Kampf begegnen?", sourceObjective = "Besiegt No-No, Ti'un den Wanderer und Blutstachel.", completion = "Ich verneige mich vor Euch, die weiterhin auf den Spuren der großen pandarischen Fabeln wandelt.", sourceObjectiveStatus = "unverified-source-field" }
