quests[33000] = { id = 33000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurfang, Krieger", sourceObjective = "Meldet Euch bei Hochfürst Saurfang in Klingenhügel in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
