quests[70865] = { id = 70865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Shattrath", description = "Ihr habt eine mysteriöse Nachricht erhalten, die Euch in ein Land fern von Azeroth beordert.\n\nFolgt dem Aufruf und findet heraus, was es in diesen neuen Landen zu entdecken gibt.", sourceObjective = "Benutzt eine Schriftrolle der Teleportation aus Eurem Inventar, um Shattrath zu erreichen, und sprecht dort mit dem mysteriösen hageren Kriegsveteran.", completion = "Seid gegrüßt, {class}. Danke, dass Ihr meinem Ruf gefolgt seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[70868] = { id = 70868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talentiert", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", sourceObjective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", sourceObjectiveStatus = "unverified-source-field" }
