quests[72522] = { id = 72522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwärender Smaragddrache", sourceObjective = "Grüße, {name}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[72523] = { id = 72523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwärender Smaragddrache", sourceObjective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnungen im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diese Gegenstände jemals verlieren, kommt zu mir zurück, und ich ersetze sie Euch kostenlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[74940] = { id = 74940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flurky", sourceObjective = "Grüße, {name}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[74941] = { id = 74941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flurky" }
quests[75491] = { id = 75491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glub", sourceObjective = "Grüße, {name}, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75492] = { id = 75492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glub", sourceObjective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnungen im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diese Gegenstände jemals verlieren, kommt zu mir zurück, und ich ersetze sie Euch kostenlos.", sourceObjectiveStatus = "unverified-source-field" }
quests[78136] = { id = 78136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Sturmwind, Hauptstadt der Allianz!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Sturmwind, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[78137] = { id = 78137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Orgrimmar, Hauptstadt der Horde!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Orgrimmar, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[78138] = { id = 78138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Donnerfels, Hauptstadt der Tauren!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Donnerfels, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung?", sourceObjectiveStatus = "unverified-source-field" }
quests[78140] = { id = 78140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", sourceObjectiveStatus = "unverified-source-field" }
quests[78151] = { id = 78151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", progress = "Ich habe ein Überlebenspaket für Eure Abenteuer zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Macht guten Gebrauch davon.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", sourceObjectiveStatus = "unverified-source-field" }
quests[78157] = { id = 78157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als {class} wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Sturmwind, Darnassus oder Eisenschmiede Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", sourceObjective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als {class} ausbilden kann.", completion = "Ihr seht jetzt schon stärker aus, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78158] = { id = 78158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als {class} wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Orgrimmar, Donnerfels oder der Unterstadt Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", sourceObjective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als {class} ausbilden kann.", progress = "Wenn Ihr bereit seid, sprecht mich an, um Eure Fähigkeiten zu trainieren.", completion = "Ihr seht jetzt schon stärker aus, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78164] = { id = 78164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talentiert", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", sourceObjective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid bereit für den Kampf, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[78165] = { id = 78165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talentiert", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", sourceObjective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", sourceObjectiveStatus = "unverified-source-field" }
quests[78166] = { id = 78166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Nordend", description = "Der Lichkönig muss für die Gräueltaten büßen, die er in unseren Landen angerichtet hat!\n\nAuf Anweisung von König Varian Wrynn wurdet Ihr gerufen, die Waffen zu ergreifen und den Schlachtzug der Allianz beim Sieg über den Lichkönig zu unterstützen.", sourceObjective = "Benutzt eine Schriftrolle der Teleportation aus Eurem Inventar, um Nordend zu erreichen, und sprecht dort mit dem Abbild der Erzmagierin Modera.", completion = "Grüße, {class}, und willkommen in den frostigen Landen von Nordend. Ihr kommt gerade rechtzeitig. Wir haben viel zu besprechen, vor allem wie wir Euch in die schwebende Stadt Dalaran schaffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[78167] = { id = 78167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talentiert", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid bereit für den Kampf, {name}!" }
quests[78168] = { id = 78168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Nordend", description = "Der Lichkönig muss für die Gräueltaten büßen, die er in unseren Landen angerichtet hat!\n\nAuf Anweisung von Kriegshäuptling Thrall wurdet Ihr gerufen, die Waffen zu ergreifen und den Schlachtzug der Horde beim Sieg über den Lichkönig zu unterstützen.", sourceObjective = "Benutzt eine Schriftrolle der Teleportation aus Eurem Inventar, um Nordend zu erreichen, und sprecht dort mit dem Abbild des Erzmagiers Aethas Sonnenhäscher.", completion = "Grüße, {class}, und willkommen in den frostigen Landen von Nordend. Ihr kommt gerade rechtzeitig. Wir haben viel zu besprechen, vor allem wie wir Euch in die schwebende Stadt Dalaran schaffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[78219] = { id = 78219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Acherus, der Schwarzen Festung, Zuflucht für alle Todesritter, die dem Lichkönig entsagen!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Acherus, der Schwarzen Festung, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[78220] = { id = 78220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", sourceObjectiveStatus = "unverified-source-field" }
quests[78221] = { id = 78221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als {class} wachsen.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", sourceObjective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als {class} ausbilden kann.", completion = "Ihr seht jetzt schon stärker aus, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78223] = { id = 78223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Nordend", description = "Der Lichkönig muss für die Gräueltaten büßen, die er in unseren Landen angerichtet hat!\n\nAuf Anweisung der Ritter der Schwarzen Klinge wurdet Ihr gerufen, die Waffen zu ergreifen und den Schlachtzug der Allianz beim Sieg über den Lichkönig zu unterstützen.", sourceObjective = "Benutzt eine Schriftrolle der Teleportation aus Eurem Inventar, um Nordend zu erreichen, und sprecht dort mit dem Abbild der Erzmagierin Modera.", sourceObjectiveStatus = "unverified-source-field" }
quests[78225] = { id = 78225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Nordend", description = "Der Lichkönig muss für die Gräueltaten büßen, die er in unseren Landen angerichtet hat!\n\nAuf Anweisung der Ritter der Schwarzen Klinge wurdet Ihr gerufen, die Waffen zu ergreifen und den Schlachtzug der Horde beim Sieg über den Lichkönig zu unterstützen.", sourceObjective = "Benutzt eine Schriftrolle der Teleportation aus Eurem Inventar, um Nordend zu erreichen, und sprecht dort mit dem Abbild des Erzmagiers Aethas Sonnenhäscher.", sourceObjectiveStatus = "unverified-source-field" }
quests[78752] = { id = 78752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweise: Titanenrune mit Protokoll Gamma", description = "Die Präsenz des Lichkönigs darf sich nicht weiter ausbreiten!\n\nDer Rat der Sechs hat erlassen, dass alle, die stark genug sind, zu den Waffen greifen und dabei helfen sollen, Azeroth zu bewahren!", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr ihm ein Medaillon der Entweihten von einem beliebigen, finalen Dungeonboss bringt.\n\nDiese Quest kann nur in einem Titanenrunendungeon mit aktivem Protokoll Gamma abgeschlossen werden.", progress = "Wir sprechen uns erneut, {name}. Bedeutet das, dass Ihr in der Erfüllung Eurer Pflichten erfolgreich wart?", completion = "Welch Übel sich darin verbirgt!\n\nIch werde es für weitere Untersuchungen zurück zum Rat der Sechs bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78753] = { id = 78753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweise: Bedrohungen für Azeroth", description = "Wir müssen den Druck an allen Fronten weiter aufrechthalten!\n\nDer Rat der Sechs hat erlassen, dass alle gewillten Kämpfer zu den Waffen greifen und dabei helfen sollen, Azeroth zu bewahren!", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr ihm ein geheimnisvolles Artefakt von einem beliebigen, finalen Dungeonboss bringt.\n\nDiese Quest kann nur in einem heroischen Dungeon abgeschlossen werden.", progress = "Wo liegt das Problem? Warum habt Ihr noch keine dieser Bedrohungen beseitigt?", completion = "Was für ein interessanter Fund!\n\nIch werde ihn für weitere Untersuchungen zurück zum Rat der Sechs bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82948] = { id = 82948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenruftafel", sourceObjective = "Begebt Euch in den Handelsdistrikt in Sturmwind und sprecht mit Melris Malagan.", completion = "Seid gegrüßt, {race}. Ich sehe, dass Ihr König Wrynns Ruf gefolgt seid.\n\nNeben mir befindet sich die Heldenruftafel, auf der Ihr eine Liste mit aktuellen Aufträgen seht. Schaut sie Euch an und entscheidet, welchen Ihr übernehmen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[82949] = { id = 82949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehlstafel des Kriegshäuptlings", sourceObjective = "Begebt Euch ins Tal der Stärke in Orgrimmar und sprecht mit dem Herold des Kriegshäuptlings.", completion = "Lok'tar, {race}. Ich sehe, dass Ihr dem Ruf des Kriegshäuptlings gefolgt seid.\n\nNeben mir befindet sich die Befehlstafel des Kriegshäuptlings, auf der Ihr eine Liste mit aktuellen Aufträgen seht. Schaut sie Euch an und entscheidet, welchen Ihr übernehmen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[82981] = { id = 82981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talentiert", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", sourceObjective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid bereit für den Kampf, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[82983] = { id = 82983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenruftafel", sourceObjective = "Nutzt eine Schriftrolle der Teleportation aus Eurem Inventar, um Sturmwind zu erreichen, und sprecht dort mit Melris Malagan.", sourceObjectiveStatus = "unverified-source-field" }
