quests[88776] = { id = 88776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Sturmwind, Hauptstadt der Allianz!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Sturmwind, der Euch als {class} ausbilden kann.", completion = "Bereit für Eure Ausbildung, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[88777] = { id = 88777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Acherus, der Schwarzen Festung, Zuflucht für alle Todesritter, die dem Lichkönig entsagen!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Acherus, der Schwarzen Festung, der Euch als {class} ausbilden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[88778] = { id = 88778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Orgrimmar, Hauptstadt der Horde!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Orgrimmar, der Euch als {class} ausbilden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[88779] = { id = 88779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Donnerfels, Hauptstadt der Tauren!\n\n<Ein/Eine:c> {class} wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", sourceObjective = "Besucht einen Trainer in Donnerfels, der Euch als {class} ausbilden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[88780] = { id = 88780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", sourceObjectiveStatus = "unverified-source-field" }
quests[88781] = { id = 88781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", sourceObjectiveStatus = "unverified-source-field" }
quests[88782] = { id = 88782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeug zum Überleben", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", sourceObjective = "Öffnet das Überlebenspaket und legt eine Waffe an.", sourceObjectiveStatus = "unverified-source-field" }
quests[88783] = { id = 88783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als {class} wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Sturmwind, Darnassus oder Eisenschmiede Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", sourceObjective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als {class} ausbilden kann.", completion = "Ihr seht jetzt schon stärker aus, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[88784] = { id = 88784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als {class} wachsen.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", sourceObjective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als {class} ausbilden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[88785] = { id = 88785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als {class} wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Orgrimmar, Donnerfels oder der Unterstadt Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", sourceObjective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als {class} ausbilden kann.", sourceObjectiveStatus = "unverified-source-field" }
