quests[91701] = { id = 91701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Dunkelmeister Gandling", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine furchtlose Gruppe zusammen und führt sie in die Tiefen von Scholomance. Reinigt Scholomance von der finsteren Präsenz von Dunkelmeister Gandling.\n\nKehrt zu mir zurück, wenn Ihr diese erhabene Aufgabe erledigt habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Dungeon von Scholomance auf erhabener Schwierigkeitsstufe ab.", completion = "{name}, Ihr habt uns einen großen Dienst erwiesen. Hoffen wir, dass die Gebeine der Toten endlich in Frieden ruhen können, nun, da Gandling sie nicht mehr stören wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[91702] = { id = 91702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Dunkelmeister Gandling", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine furchtlose Gruppe zusammen und führt sie in die Tiefen von Scholomance. Reinigt Scholomance von der finsteren Präsenz von Dunkelmeister Gandling.\n\nKehrt zu mir zurück, wenn Ihr diese erhabene Aufgabe erledigt habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Dungeon von Scholomance auf erhabener Schwierigkeitsstufe ab.", completion = "{name}, Ihr habt uns einen großen Dienst erwiesen. Hoffen wir, dass die Gebeine der Toten endlich in Frieden ruhen können, nun, da Gandling sie nicht mehr stören wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[91703] = { id = 91703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Flammenwirker Koegler", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine gewitzte Gruppe zusammen und führt sie in die Tiefen der Scharlachroten Hallen. Beschwört die Macht der Erhabenen und setzt dem bücherverbrennenden Treiben von Flammenwirker Koegler ein Ende.", sourceObjective = "Schließt den Dungeon der Scharlachroten Hallen auf erhabener Schwierigkeitsstufe ab.", sourceObjectiveStatus = "unverified-source-field" }
