quests[91705] = { id = 91705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Durand", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine tapfere Gruppe zusammen und führt sie ins Scharlachrote Kloster. Beschwört die Macht der Erhabenen und zerschmettert Durand mit gerechtem Zorn.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Scharlachrote Kloster auf erhabener Schwierigkeitsstufe ab.", completion = "{name}, Ihr seid ein tapferer {class}. Eure Freunde und Eure Gilde werden über die Geschwindigkeit und Wildheit staunen, mit der Ihr das Scharlachrote Kloster erobert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[91706] = { id = 91706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Durand", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine tapfere Gruppe zusammen und führt sie ins Scharlachrote Kloster. Beschwört die Macht der Erhabenen und zerschmettert Durand mit gerechtem Zorn.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Scharlachrote Kloster auf erhabener Schwierigkeitsstufe ab.", completion = "{name}, Ihr seid ein tapferer {class}. Eure Freunde und Eure Gilde werden über die Geschwindigkeit und Wildheit staunen, mit der Ihr das Scharlachrote Kloster erobert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[91707] = { id = 91707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Schwadronsführer Ner'onok", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine scharfsichtige Gruppe zusammen und führt sie zur Belagerung des Niuzaotempels. Beschwört die Macht der Erhabenen und bringt Schwadronsführer Ner'onok zu Boden.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt die Belagerung des Niuzaotempels auf erhabener Schwierigkeitsstufe ab.", completion = "{name}, das war unglaublich. Ner'onok ist ein Meistertaktiker, doch Ihr habt ihm eine schmerzliche Lektion erteilt.", sourceObjectiveStatus = "unverified-source-field" }
quests[91708] = { id = 91708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Schwadronsführer Ner'onok", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine scharfsichtige Gruppe zusammen und führt sie zur Belagerung des Niuzaotempels. Beschwört die Macht der Erhabenen und bringt Schwadronsführer Ner'onok zu Boden.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt die Belagerung des Niuzaotempels auf erhabener Schwierigkeitsstufe ab.", completion = "{name}, das war unglaublich. Ner'onok ist ein Meistertaktiker, doch Ihr habt ihm eine schmerzliche Lektion erteilt.", sourceObjectiveStatus = "unverified-source-field" }
quests[91709] = { id = 91709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Raigonn", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine erstklassige Gruppe zusammen und führt sie zum Tor der Untergehenden Sonne. Beschwört die Macht der Erhabenen und vernichtet Raigonn.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Tor der Untergehenden Sonne auf erhabener Schwierigkeitsstufe ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[91710] = { id = 91710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Raigonn", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine erstklassige Gruppe zusammen und führt sie zum Tor der Untergehenden Sonne. Beschwört die Macht der Erhabenen und vernichtet Raigonn.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Tor der Untergehenden Sonne auf erhabener Schwierigkeitsstufe ab.", completion = "Das war ein wahres Meisterstück, {name}. Ich habe noch nie jemanden so schnell einen Riesen zu Fall bringen sehen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[91711] = { id = 91711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Xin der Waffenmeister", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine flinke Gruppe zusammen und führt sie zum Mogu'shanpalast. Beschwört die Macht der Erhabenen und macht Xin dem Waffenmeister ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Mogu'shanpalast auf erhabener Schwierigkeitsstufe ab.", completion = "Vielen Dank, {name}. Eure Kampfkunst sucht ihresgleichen, und Eure Eilfertigkeit wird die Herzen Eurer Widersacher mit Furcht erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91712] = { id = 91712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Xin der Waffenmeister", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine flinke Gruppe zusammen und führt sie zum Mogu'shanpalast. Beschwört die Macht der Erhabenen und macht Xin dem Waffenmeister ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Mogu'shanpalast auf erhabener Schwierigkeitsstufe ab.", completion = "Vielen Dank, {name}. Eure Kampfkunst sucht ihresgleichen, und Eure Eilfertigkeit wird die Herzen Eurer Widersacher mit Furcht erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[91713] = { id = 91713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Sha des Hasses", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine ruhige Gruppe zusammen und führt sie zum Shado-Pan-Kloster. Beschwört die Macht der Erhabenen und rettet Taran Zhu vor dem Sha des Hasses.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Shado-Pan-Kloster auf erhabener Schwierigkeitsstufe ab.", completion = "Seid reich gesegnet, {name}. Diese Welt so schnell vom Hass zu befreien, ist eine Leistung, die großzügig belohnt werden sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[91714] = { id = 91714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Sha des Hasses", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine ruhige Gruppe zusammen und führt sie zum Shado-Pan-Kloster. Beschwört die Macht der Erhabenen und rettet Taran Zhu vor dem Sha des Hasses.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt das Shado-Pan-Kloster auf erhabener Schwierigkeitsstufe ab.", completion = "Seid reich gesegnet, {name}. Diese Welt so schnell vom Hass zu befreien, ist eine Leistung, die großzügig belohnt werden sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[91715] = { id = 91715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Yan-Zhu der Dekantierte", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine beherzte Gruppe zusammen und führt sie zur Brauerei Sturmbräu. Beschwört die Macht der Erhabenen und helft Yan-Zhu dem Dekantierten, sich zu verdünnisieren.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt die Brauerei Sturmbräu auf erhabener Schwierigkeitsstufe ab.", completion = "Meinen aufrichtigen Dank, {name}. Wenn es kein Sturmbräu gäbe, um die Sorgen nach einem harten Tag hinunterzuspülen, wäre die Welt ein wahrlich trister Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[91716] = { id = 91716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Yan-Zhu der Dekantierte", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine beherzte Gruppe zusammen und führt sie zur Brauerei Sturmbräu. Beschwört die Macht der Erhabenen und helft Yan-Zhu dem Dekantierten, sich zu verdünnisieren.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt die Brauerei Sturmbräu auf erhabener Schwierigkeitsstufe ab.", completion = "Meinen aufrichtigen Dank, {name}. Wenn es kein Sturmbräu gäbe, um die Sorgen nach einem harten Tag hinunterzuspülen, wäre die Welt ein wahrlich trister Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[91717] = { id = 91717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Sha des Zweifels", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine beherzte Gruppe zusammen und führt sie zum Tempel der Jadeschlange. Beschwört die Macht der Erhabenen und vernichtet das Sha des Zweifels.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Tempel der Jadeschlange auf erhabener Schwierigkeitsstufe ab.", completion = "Mein Dank ist Euch gewiss, {name}. Ihr habt heute großen Mut an den Tag gelegt und die Herausforderung in Windeseile bewältigt. Eure Freunde werden beeindruckt und Eure Gegner verängstigt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[91718] = { id = 91718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine erhabene Herausforderung: Sha des Zweifels", description = "{name}, die Erhabenen brauchen Eure Hilfe. Stellt eine beherzte Gruppe zusammen und führt sie zum Tempel der Jadeschlange. Beschwört die Macht der Erhabenen und vernichtet das Sha des Zweifels.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", sourceObjective = "Schließt den Tempel der Jadeschlange auf erhabener Schwierigkeitsstufe ab.", completion = "Mein Dank ist Euch gewiss, {name}. Ihr habt heute großen Mut an den Tag gelegt und die Herausforderung in Windeseile bewältigt. Eure Freunde werden beeindruckt und Eure Gegner verängstigt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[91786] = { id = 91786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn der Zweifel nagt", description = "Während meiner Zeit hier habe ich die eine oder andere Pandarenweisheit aufgeschnappt. Ganz besonders gefällt mir diese hier:\n\n\"Die Zaghaften zweifeln, bevor es Probleme gibt, die Feiglinge zweifeln, wenn es Probleme gibt. Die Tapfersten unter uns aber zweifeln erst, wenn alle Probleme überstanden sind.\"\n\nOb das wirklich stimmt, wage ich zu bezweifeln, aber ich zähle mich nicht zu den Zaghaften.\n\nDas Sha des Zweifels ist in den Tempel der Jadeschlange geflohen. Verfolgt es, besiegt es, und reißt ihm den Geist heraus. Dafür werdet Ihr die Hilfe der Erhabenen benötigen.", sourceObjective = "Bezwingt das Sha des Zweifels im Tempel der Jadeschlange auf erhabener Schwierigkeitsstufe und holt Euch die Schimäre des Zweifels.", progress = "Noch eine pandarische Weisheit: \"Nicht das Scheitern fürchten wir, sondern den Zweifel selbst.\" Indem wir uns unseren Zweifeln stellen, gewinnen wir große Stärke.\n\nHabt Ihr Euch Euren Zweifeln gestellt, {name}?", completion = "Ihr habt es geschafft!\n\nManche mögen ja auf Magie oder Stahl vertrauen, doch nach meiner Erfahrung ist der Zweifel die mächtigste Waffe, die man gegen seine Feinde führen kann. Setzt sie gekonnt ein, und Eure Gegner werden gar nicht erst gegen Euch kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[92336] = { id = 92336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Tränke", description = "Tränke, Tränke, Tränke. Was ich Euch alles über Tränke beibringen könnte!\n\nBringt mir Proben Eurer Arbeit, damit ich weiß, dass Ihr bereit dazu seid.\n\nVergesst nicht, {name}, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Tränkebeherrschung abgeschlossen habt, werden Euch Spezialisierungen für Tränke und Transmutationen nicht mehr angeboten.", sourceObjective = "Bringt eine große Anzahl Tränke zu einem Alchemielehrer in einer beliebigen Hauptstadt.", progress = "Habt Ihr die Tränke?", completion = "Hervorragend!", sourceObjectiveStatus = "unverified-source-field" }
quests[92337] = { id = 92337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Elixiere", description = "Bei Elixieren geht es nur um Stärke! Ich kann Euch zum Meister der Elixiere ausbilden, wenn Ihr das wünscht.\n\nDas ist nichts für jeden und ich verlange einen Beweis für Eure Ernsthaftigkeit, bevor wir fortfahren können. Mit einigen Fläschchen könnt Ihr mir Eure Entschlossenheit zeigen.\n\nVergesst nicht, {name}, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Elixierbeherrschung abgeschlossen habt, werden Euch Spezialisierungen für Tränke und Transmutationen nicht mehr angeboten.", sourceObjective = "Bringt eine Reihe verschiedener Fläschchen zu einem Alchemielehrer in einer beliebigen Hauptstadt.", progress = "Habt Ihr die Fläschchen?", completion = "Sehr gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[92338] = { id = 92338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Transmutation", description = "Eisen zu Gold, Wasser zu Feuer... Ich kann Euch helfen, wenn Ihr die Transmutation meistern wollt.\n\nDie Ausbildung ist sehr teuer, also müsst Ihr mir einige der besten transmutierten Materialien der Welt bringen.\n\nVergesst nicht, {name}, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Transmutationsbeherrschung abgeschlossen habt, werden Euch Spezialisierungen für Tränke und Transmutationen nicht mehr angeboten.", sourceObjective = "Bringt die verlangten Materialien zu einem Alchemielehrer in einer beliebigen Hauptstadt.", progress = "Habt Ihr die Materialien?", completion = "Sehr gut!", sourceObjectiveStatus = "unverified-source-field" }
